"""Drift gate: a hand-edited generated file fails; a header-only version change does not.

modelgen is never run here; the generator is injected (seam 1).
"""

import importlib.util
import subprocess
from pathlib import Path

import pytest

_SPEC = importlib.util.spec_from_file_location(
    "validate", Path(__file__).resolve().parent.parent / "contracts" / "validate.py"
)
validate = importlib.util.module_from_spec(_SPEC)
_SPEC.loader.exec_module(validate)

OUT = "dbt/tests/generated"
HEADER = "-- GENERATED by modelgen {v} from some_contract 1.0.0. Do not edit.\n"
BODY = "select 1 as failure\n"


def _repo(tmp_path, version="0.16.0"):
    (tmp_path / ".modelgen.yml").write_text(
        "sources_contracts: contracts/x.odcs.yaml\nsources_output: dbt/models\n"
        "tests_output: dbt/tests\n"
    )
    f = tmp_path / OUT / "a.sql"
    f.parent.mkdir(parents=True)
    f.write_text(HEADER.format(v=version) + BODY)
    return f


def _generator(version="0.16.0", body=BODY):
    def gen(workdir):
        f = Path(workdir) / OUT / "a.sql"
        f.parent.mkdir(parents=True)
        f.write_text(HEADER.format(v=version) + body)

    return gen


def test_clean_tree_passes(tmp_path):
    _repo(tmp_path)
    assert validate.check_generated(tmp_path, _generator()) == []


def test_hand_edit_fails(tmp_path):
    f = _repo(tmp_path)
    f.write_text(f.read_text() + "-- tweaked by hand\n")
    problems = validate.check_generated(tmp_path, _generator())
    assert len(problems) == 1 and "a.sql" in problems[0]


def test_header_only_version_difference_passes(tmp_path):
    _repo(tmp_path, version="0.15.0")
    assert validate.check_generated(tmp_path, _generator("0.16.0")) == []


def test_version_change_plus_body_edit_fails(tmp_path):
    f = _repo(tmp_path, version="0.15.0")
    f.write_text(f.read_text().replace("1 as", "2 as"))
    assert validate.check_generated(tmp_path, _generator("0.16.0"))


def test_deleted_generated_file_fails(tmp_path):
    _repo(tmp_path).unlink()
    assert validate.check_generated(tmp_path, _generator())


def test_stale_generated_file_fails(tmp_path):
    _repo(tmp_path)
    stale = tmp_path / OUT / "old.sql"
    stale.write_text(HEADER.format(v="0.16.0") + BODY)
    problems = validate.check_generated(tmp_path, _generator())
    assert len(problems) == 1 and "old.sql" in problems[0]


def _modelgen_works():
    try:
        return subprocess.run(["modelgen", "--version"], capture_output=True).returncode == 0
    except OSError:
        return False


@pytest.mark.skipif(not _modelgen_works(), reason="modelgen not runnable here")
def test_real_repo_is_in_sync():
    root = Path(__file__).resolve().parent.parent
    assert validate.check_generated(root) == []
